\lambda_2+\lambda_3&>0.
\end{align*}

A {\em heteroclinic graph} $\Gamma$ for a diffeomorphism $f$ is a directed graph, not necessarily finite, such that:
\begin{itemize}
\item each of its vertices is a chain-recurrent hyperbolic set,
\item each edge from vertex $K$ to vertex $L$ is an orbit whose $\alpha$-limit and $\omega$-limit are subsets of $K$ and $L$, respectively,
\end{itemize}

\label{t.homcor}
Let $r\geq 2$ be an integer. If a saddle $P$ of $f\in {Diff}^r(M)$ is in the support $\Lambda$ of a Eulerian heteroclinic graph that has mechanically no dominated splitting of indices $i\in I$, then for any open set $U$ containing $\Lambda$, there exists an open set ${\mathcal U}\subset {Diff}^r(M)$ such that:
\begin{itemize}
\item $f$ is in the closure of ${\mathcal U}$,
\item for any $g$ in ${\mathcal U}$, the continuation $P_g$ of the saddle $P$ is in an infinitely connected heteroclinic graph $\Delta_g$ supported in $U$, that contains infinitely many mechanical obstructions to domination of each index $i\in I$.
\end{itemize}

\label{p.gathering}
Let $r\geq 2$ be an integer. Let $f\in {Diff}^r(M)$ be a diffeomorphism admitting a finite heteroclinic graph
$$\Gamma=\Bigl(\{K_0,...,K_m\},\{e_1,...,e_n\}\Bigr).$$
and assume that $\gamma=(K_0,e_1,K_1,\ldots K_{k-1},e_k,K_k)$ is a trail that contains mechanical obstructions to domination of any index $i$ in a set $I$. Let $\epsilon>0$ and $U$ a neighborhood of $K_1\cup \ldots \cup K_{k-1}$.

Then there is an $\epsilon$-perturbation $g$ of $f$ in ${Diff}^r(M)$ and a heteroclinic graph for $g$
$$\tilde{\Gamma}=\Bigl(\{\tilde{K}_0,...,\tilde{K}_m\},\{\tilde{e},\tilde{e}_{k+1},...,\tilde{e}_n\}\Bigr)$$
such that $g=f$ outside $U$, and
\begin{itemize}
\item $(\tilde{K}_0,\tilde{e},\tilde{K}_k)$ is a trail that contains mechanical obstructions of all indices $i\in I$.
\item for all $0\leq \ell\leq m$, the basic set $\tilde{K}_\ell$ for $g$ is the continuation of the basic set $K_\ell$ for $f$ and retains its initial mechanical obstructions to domination, for all indices $i\notin I$.\footnote{Note that the vertices are not necessarily disjoint basic sets, which is why all the vertices, and not only vertices $K_1, \ldots ,K_{k-1}$, may loose domination of indices $i\in I$.}
\item for $\ell>k$, if $e_\ell$ is an edge from $K_p$ to $K_q$, then $\tilde{e}_\ell$ is an edge from $\tilde{K}_p$ to $\tilde{K}_q$ whose hausdorff distance to $e_\ell$ is less than $\epsilon$. Moreover, for any bundle tangency at $e_\ell$, there is a bundle tangency of same indices at $\tilde{e}_\ell$.
\end{itemize}

\label{p.robustizing}
Fix $r>1$ and $f\in {Diff}^r(M)$. Let $\Gamma=\bigl(\{K\},\{e\}\bigr)$ be a heteroclinic graph for $f$ formed by a single loop $(K,e,K)$, and containing mechanical obstructions to domination of index $i$, for any integer $i$ in a set $I$.

Then there exists an open set ${\mathcal U}\in {Diff}^r(M)$ containing $f$ in its closure such that, for any $g\in {\mathcal U}$,
\begin{itemize}
\item there is an infinitely connected heteroclinic graph $\tilde{\Gamma}$ for $g$ that contains the continuation $\tilde{K}$ of $K$,
\item  $\tilde{\Gamma}$ contains infinitely many mechanical obstructions to domination for each index $i\in I$,
\item the Hausdorff distance between the supports of $\Gamma$ and   $\tilde{\Gamma}$ is less than $\epsilon$.
\end{itemize}

\label{c.Lyapgraph}
Let $r\geq 1$. There is a residual subset ${\mathcal R} \subset {Diff}^r(M)$ such that if 
\begin{itemize}
\item $f$ is a diffeomorphism in ${\mathcal R}$,
\item $\mu$ is an $f$-invariant probability measure $\mu$ supported in a heteroclinic class $\operatorname{Het}(P,f)$, with Lyapunov map $\sigma\colon \{0,\ldots,d\}\to \mathbb{R}$,
\item $I$ is the set of integers $0\leq i\leq d$ such that there is no mechanical obstruction to domination of index $i$ on $\operatorname{Het}(P,f)$ -- we have $0,d\in I$ --
\end{itemize}
then any convex map $\tau\geq \sigma$ coinciding with $\sigma$ at indices $i\in I$ is the limit Lyapunov map of a sequence of periodic $f$-invariant measures $\mu_n$ converging weakly to $\mu$. 

Moreover, that sequence can be chosen so that the supports $\mathrm{supp} (\mu_n)$ converge to the homoclinic class $\operatorname{Hom}(P,f)$ for the Hausdorff topology.

\label{t.Lyaptang}
Let $r\geq 2$. Let $\Lambda$ be a homoclinic tangency for a diffeomorphism $f\in {Diff}^r(M)$.
Then ${\mathcal G}(\Lambda)$ is precisely the set of possible limit Lyapunov maps: $\tau\in {\mathcal G}(\Lambda)$ if and only if there are
\begin{itemize}
\item a sequence of diffeomorphisms $f_n$ converging to $f$ in ${Diff}^r(M)$
\item a sequence of periodic measures $\mu_n\in {\mathcal M}(f_n)$ where the supports $\mathrm{supp} \mu_n$ converge to a subset of $\Lambda$ for the Hausdorff topology,
\end{itemize}
such that $\tau=\lim_{n\to \infty}\sigma(\mu_n)$. Moreover, for any open set  $U\supset \Lambda$, there exists an open set ${\mathcal U}\subset {Diff}^r(M)$

such that:
\begin{itemize}
\item $f$ is in the closure $\overline{{\mathcal U}}$,
\item for any diffeomorphism $g$ in a residual subset ${\mathcal R}\subset {\mathcal U}$, if $\Pi_{g_{|U}}$ is the set of Lyapunov maps of periodic measures for the restriction $g_{|U}$, then the closure $\overline{\Pi_{g_{|U}}}$ is a neighborhood  in ${\mathbb R}^d$ of the polytope ${\mathcal G}(\Lambda)$.
\end{itemize}

\cref{t.Lyaptang} also holds
\begin{itemize}
\item if $\Lambda$ is the closure of the orbit of a homoclinic point for $P$,
\item in the $C^{1+\alpha}$ topologies. One needs however to adapt the statement the same way we adapted the statement of \cref{t.lambda} to obtain \cref{t.lambdaalpha}.
\end{itemize}
